CREATE TABLE password_history (id UUID PRIMARY KEY DEFAULT uuid_v7(),item_id UUID NOT NULL,vault_id UUID NOT NULL,owner_id UUID NOT NULL,revision BIGINT NOT NULL,encrypted_payload TEXT NOT NULL,created_at TIMESTAMPTZ NOT NULL DEFAULT now(),FOREIGN KEY(item_id) REFERENCES password_vault_item(id),FOREIGN KEY(vault_id) REFERENCES password_vault(id),UNIQUE(item_id,revision)); CREATE INDEX idx_password_history_item ON password_history(item_id,revision DESC);
